sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    api.setState('sampleSize', api.data.get_existing_supporting_data.output.sampleSize);
    if (api.data.get_existing_supporting_data.output.sourceTableLabel)
        api.setState('sourceTable', api.data.get_existing_supporting_data.output.sourceTableLabel);
    if (api.data.get_existing_supporting_data.output.sourceTable)
        api.setState('sourceTableId', api.data.get_existing_supporting_data.output.sourceTable);
    if (api.data.get_existing_supporting_data.output.supportingDataFields)
        api.setState('supportingDataFields', api.data.get_existing_supporting_data.output.supportingDataFields);
    if (api.data.get_existing_supporting_data.output.type != 'script')
        api.setState('isScriptType', false);
    if (api.data.get_existing_supporting_data.output.sampleCollectionType)
        api.setState('sampleCollectionType', api.data.get_existing_supporting_data.output.sampleCollectionType);

    if (api.data.get_existing_supporting_data.output.sampleCollectionType == 'count') {
        api.setState('sampleSizeDisplayLabel', api.state.sampleSizeLabel);
    } else if (api.data.get_existing_supporting_data.output.sampleCollectionType == 'percentage') {
        api.setState('sampleSizeDisplayLabel', api.state.samplePercentageLabel);
        api.setState('isSampleSizeRequired', true);
        if (!api.data.get_existing_supporting_data.output.sampleSize) {
            api.setState('disableSave', true);
        }
    }

}
